```go
func runSetupFlow(ctx context.Context, w io.Writer, opts EnableOptions) error {
    external.DiscoverAndRegisterAlways(ctx)

    var selectFn func(available []string) ([]string, error)
    if opts.Yes {
        selectFn = selectAllAgents
    }

    // Compute fresh-repo state ONCE, before any settings writes.
    isFresh := false
    if _, err := paths.WorktreeRoot(ctx); err == nil && !settings.IsSetUpAny(ctx) {
        upstream, probeErr := upstreamHasEntireSettings(ctx)
        if probeErr != nil {
            logging.Debug(ctx, "upstream settings probe failed; treating as fresh repo",
                slog.String("error", probeErr.Error()))
        }
        if upstream {
            fmt.Fprintln(w, "Existing Entire setup detected on origin. Run `git pull` first to adopt it, then re-run `entire enable`.")
            return NewSilentError(errors.New("upstream entire setup already exists"))
        }
        isFresh = true
    }

    agents, err := detectOrSelectAgent(ctx, w, selectFn)
    if err != nil {
        return fmt.Errorf("agent selection failed: %w", err)
    }

    if err := runEnableInteractive(ctx, w, agents, opts); err != nil {
        return err
    }

    if isFresh {
        if err := applyCustomMetadataRef(ctx, w); err != nil {
            return fmt.Errorf("apply custom metadata ref: %w", err)
        }
    }
    return nil
}
```

