func parseCheckpointsVersion(val any) (int, bool) {
    if v, ok := val.(int); ok && (v == 1 || v == 2) {
        return v, true
    }
    if f, ok := val.(float64); ok {
        switch f {
        case 1.0, 1.1:
            return 1, true
        case 2.0:
            return 2, true
        }
    }
    if s, ok := val.(string); ok {
        switch s {
        case "1", "1.1":
            return 1, true
        case "2":
            return 2, true
        }
        // Fallback for "1.0", "2.0" style strings via Atoi-on-integer-portion only.
        if n, err := strconv.Atoi(s); err == nil && (n == 1 || n == 2) {
            return n, true
        }
    }
    return 1, false
}
```

Note: the existing function used `strconv.Atoi` first for strings; this rewrite checks the exact "1.1" string before falling back to `Atoi`. The signature is unchanged so `CheckpointsVersion()` and `IsCheckpointsV2Enabled()` callers stay correct.

